window.products.push({"id":254438,"name":"RGF REME HVAC-305 Air Purification System Light REPLACEMENT (PHIC-9R-GA)","category":"homeandappliances","retail price":165.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81rh4T1KyGL._AC_SL1500_.jpg","description":"PHI Technology (Photohydroionization) creates a group of “Friendly Oxidizers” (Super Oxide Ions, Hydro-Peroxides, Hydroxides.) Oxidizers revert back into O2 and H2O. Oxidizers are extremely effective at destroying microbes and gases. All of the oxidizers created exist in outside air already. It doesn't harm people.","images":["https://m.media-amazon.com/images/I/81rh4T1KyGL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"RGF","source_asin":"B004FH36A0","category_path":"Home & Kitchen"},"sku":"BM-254438","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B004FH36A0","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B004FH36A0","price_pending":true,"merchant_ready":false});
